}

Method.Source:
/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>New Controller Object</returns>
public static METDeliveryNotePostingController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METDeliveryNotePostingController controller = new METDeliveryNotePostingController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METDeliveryNotePostingService), methodstr(METDeliveryNotePostingService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Main method for delivery notes posting batch job
/// </summary>
/// <param name = "_args">_args for construct the controller</param>
public static void main(Args _args)
{
    METDeliveryNotePostingController    controller;

    /// create controller
    controller = METDeliveryNotePostingController::construct(_args);

    // execute the service class
    controller.startOperation();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:ReturnOrderDeliveryNote";
}
